/* From Uiverse.io by xantha01 - Tags: button, arrow, startbutton  */
.__UIV_SCOPE__ .swipe {
  position: relative;
  background-color: #F1F7F7;
  width: 200px;
  height: 60px;
  color: rgba(255, , 204, 1);
  border-radius: 60px;
  display: flex;
  justify-content: center;
  align-items: center;
  text-decoration: none;
  letter-spacing: 2px;
  border-top: 0.5px solid rgba(0, 0, 0, 0.35);
  border-left: 0.5px solid rgba(0, 0, 0, 0.35);
  padding-left: 40px;
  cursor: pointer;
  transition: 0.35s ease;
}

.__UIV_SCOPE__ .swipe:hover {
  padding-left: 0;
  padding-right: 40px;
  color: #324B4C;
}

.__UIV_SCOPE__ .container {
  position: absolute;
  left: 5px;
  width: 50px;
  height: 50px;
  background: #7AB5B7;
  border-radius: 50%;
  transition: 0.35s ease;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #f1f4f7;
}

.__UIV_SCOPE__ .swipe:hover .container {
  left: calc(100% - 55px);
  color: #324B4C;
}
